mutations.before:
const setField = (el: HTMLElement, value: string) => {
  fireEvent.click(el);
  el.focus();
  fireEvent.change(el, { target: { value } });
};

mutations.after:
const setField = (el: HTMLElement, value: string) => {
  fireEvent.click(el);
  fireEvent.change(el, { target: { value } });
};
